7407242007012006','196904211992021001')
                LIMIT {$batchSize} OFFSET {$offset}
            ")->result_array();

            if (empty($pegawai_rows)) break;

            foreach ($pegawai_rows as $row) {
                $pegawai_id = trim($row['PEGAWAI_ID']);
                echo "====================================================\n";
                echo "PEGAWAI ID : {$pegawai_id}\n";
                flush();

                try {
                    $pegawai = $this->db->query("
                        SELECT
                            p.PEGAWAI_ID,
                            p.NIP_BARU,
                            p.NAMA,
                            p.LATITUDE AS rumah_latitude,
                            p.LONGITUDE AS rumah_longitude,
                            tp.latitude AS presensi_latitude,
                            tp.longitude AS presensi_longitude
                        FROM pegawai p
                        JOIN pegawai_titik_presensi tp ON tp.nip_baru = p.NIP_BARU
                        WHERE p.PEGAWAI_ID = '{$pegawai_id}'
                        LIMIT 1
                    ")->row();

                    if (!$pegawai) {
                        echo "Pegawai tidak ditemukan\n";
                        continue;
                    }

                    if (empty($pegawai->rumah_latitude) || empty($pegawai->rumah_longitude) ||
                        empty($pegawai->presensi_latitude) || empty($pegawai->presensi_longitude)) {
                        echo "Koordinat tidak lengkap\n";
                        continue;
                    }

                    echo "Nama : {$pegawai->NAMA}\n";
                    echo "NIP : {$pegawai->NIP_BARU}\n";

                    $url = "http://osrm-java:5000/route/v1/driving/" .
                        $pegawai->rumah_longitude . "," . $pegawai->rumah_latitude . ";" .
                        $pegawai->presensi_longitude . "," . $pegawai->presensi_latitude .
                        "?overview=false";

                    $context = stream_context_create(['http' => ['timeout' => 10]]);
                    $response = @file_get_contents($url, false, $context);

                    if (!$response) {
                        echo "Gagal akses OSRM\n";
                        continue;
                    }

                    $osrm = json_decode($response, true);
                    if (!isset($osrm['routes'][0])) {
                        echo "Route tidak ditemukan\n";
                        continue;
                    }

                    $jarak_meter = $osrm['routes'][0]['distance'];
                    $jarak_km = round($jarak_meter / 1000, 3);

                    echo "Jarak : {$jarak_meter} meter\n";
                    echo "Jarak : {$jarak_km} km\n";

                    $data = [
                        'pegawai_id'         => $pegawai->PEGAWAI_ID,
                        'nip_baru'           => $pegawai->NIP_BARU,
                        'nama_pegawai'       => $pegawai->NAMA,
                        'rumah_latitude'     => $pegawai->rumah_latitude,
                        'rumah_longitude'    => $pegawai->rumah_longitude,
                        'presensi_latitude'  => $pegawai->presensi_latitude,
                        'presensi_longitude' => $pegawai->presensi_longitude,
                        'jarak_meter'        => $jarak_meter,
                        'jarak_km'           => $jarak_km
                    ];

                    $this->db->replace('pegawai_jarak_presensi', $data);
                    echo "SUKSES SIMPAN\n\n";

                } catch (Exception $e) {
                    echo "ERROR : " . $e->getMessage() . "\n";
                }
            }

            $offset += $batchSize;
            echo "\n--- Selesai batch, lanjut ke offset {$offset} ---\n\n";
            sleep(1); // jeda antar batch

        } while (true);

        echo "\n====================================================\n";
        echo "SELESAI\n";
    }
